"use client"

import { Suspense, useState, useCallback, useMemo } from "react"
import { useSearchParams } from "next/navigation"
import dynamic from "next/dynamic"
import { DashboardShell } from "@/components/dashboard/dashboard-shell"
import { AlertPanel } from "@/components/dashboard/alert-panel"
import { AlertDetail } from "@/components/dashboard/alert-detail"
import { SeverityStats } from "@/components/dashboard/severity-stats"
import { WeatherPanel } from "@/components/dashboard/weather-panel"
import { CommunityReportForm } from "@/components/dashboard/community-report-form"
import { ReportsList } from "@/components/dashboard/reports-list"
import { PipelineStatus } from "@/components/dashboard/pipeline-status"
import { HazardChart } from "@/components/dashboard/hazard-chart"
import { Button } from "@/components/ui/button"
import { Badge } from "@/components/ui/badge"
import { cn } from "@/lib/utils"
import {
  useAlerts,
  useWeather,
  usePipelineStatus,
  useCommunityReports,
} from "@/hooks/use-afro-storm"
import type { HazardAlert, Severity, HazardType } from "@/lib/types"
import {
  AlertTriangle,
  Cloud,
  Users,
  BarChart3,
  Database,
  FileText,
  Plus,
  Wind,
  Waves,
  Sun,
  Flame,
  MapPin,
  Filter,
  X,
} from "lucide-react"
import {
  CycloneTrackVisualization,
  FloodMonitorVisualization,
  DroughtMonitorVisualization,
  WildfireTrackerVisualization,
} from "@/components/visualizations"

const AfricaMap = dynamic(
  () =>
    import("@/components/dashboard/africa-map").then((mod) => ({
      default: mod.AfricaMap,
    })),
  {
    ssr: false,
    loading: () => (
      <div className="flex items-center justify-center h-full bg-card rounded-lg border border-border">
        <div className="flex flex-col items-center gap-3">
          <div className="h-8 w-8 border-2 border-primary border-t-transparent rounded-full animate-spin" />
          <p className="text-sm text-muted-foreground font-mono">
            Loading Map...
          </p>
        </div>
      </div>
    ),
  }
)

type AnalyticsView = "overview" | "alerts" | "weather" | "community" | "pipeline"

const HAZARD_TYPES: { type: HazardType | "ALL"; label: string; icon: React.ElementType; color: string }[] = [
  { type: "ALL", label: "All Hazards", icon: MapPin, color: "bg-primary" },
  { type: "CYCLONE", label: "Cyclones", icon: Wind, color: "bg-severity-red" },
  { type: "FLOOD", label: "Floods", icon: Waves, color: "bg-severity-orange" },
  { type: "DROUGHT", label: "Droughts", icon: Sun, color: "bg-yellow-500" },
  { type: "WILDFIRE", label: "Wildfires", icon: Flame, color: "bg-red-600" },
  { type: "EARTHQUAKE", label: "Earthquakes", icon: AlertTriangle, color: "bg-purple-500" },
]

export default function AnalyticsPageWrapper() {
  return (
    <Suspense fallback={null}>
      <AnalyticsPage />
    </Suspense>
  )
}

function AnalyticsPage() {
  const searchParams = useSearchParams()
  const viewParam = searchParams.get("view") as AnalyticsView | null
  const currentView: AnalyticsView = viewParam || "overview"

  const [selectedAlert, setSelectedAlert] = useState<HazardAlert | null>(null)
  const [severityFilter, setSeverityFilter] = useState<Severity | null>(null)
  const [hazardTypeFilter, setHazardTypeFilter] = useState<HazardType | "ALL">("ALL")

  const { data: alertsData } = useAlerts()
  const { data: weatherData, isLoading: weatherLoading } = useWeather()
  const { data: pipelineData, isLoading: pipelineLoading } = usePipelineStatus()
  const {
    data: reportsData,
    isLoading: reportsLoading,
    mutate: mutateReports,
  } = useCommunityReports()

  const alerts: HazardAlert[] = alertsData?.alerts || []
  const reports = reportsData?.reports || []

  // Filter alerts based on selected hazard type and severity
  const filteredAlerts = useMemo(() => {
    return alerts.filter((alert) => {
      const matchesType = hazardTypeFilter === "ALL" || alert.hazard_type === hazardTypeFilter
      const matchesSeverity = !severityFilter || alert.severity === severityFilter
      return matchesType && matchesSeverity
    })
  }, [alerts, hazardTypeFilter, severityFilter])

  const alertCounts = useMemo(
    () => ({
      red: alerts.filter((a) => a.severity === "RED").length,
      orange: alerts.filter((a) => a.severity === "ORANGE").length,
      yellow: alerts.filter((a) => a.severity === "YELLOW").length,
      green: alerts.filter((a) => a.severity === "GREEN").length,
    }),
    [alerts]
  )

  // Count by hazard type
  const hazardCounts = useMemo(() => {
    const counts: Record<string, number> = {}
    alerts.forEach((alert) => {
      counts[alert.hazard_type] = (counts[alert.hazard_type] || 0) + 1
    })
    return counts
  }, [alerts])

  const handleAlertClick = useCallback((alert: HazardAlert) => {
    setSelectedAlert(alert)
  }, [])

  const clearFilters = () => {
    setHazardTypeFilter("ALL")
    setSeverityFilter(null)
  }

  return (
    <DashboardShell alertCounts={alertCounts}>
      <main className="flex-1 overflow-y-auto p-4 lg:p-5">
        {/* ========== COMMAND CENTER (Unified Overview) ========== */}
        {currentView === "overview" && (
          <div className="space-y-4">
            {/* Severity Stats */}
            <SeverityStats alerts={alerts} />

            {/* Unified Map Section with Hazard Filters */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
              {/* Map - 2/3 */}
              <div className="lg:col-span-2 space-y-3">
                {/* Hazard Type Filter Bar */}
                <div className="flex flex-wrap items-center gap-2">
                  <div className="flex items-center gap-1.5 text-xs text-muted-foreground mr-2">
                    <Filter className="h-3.5 w-3.5" />
                    Filter:
                  </div>
                  {HAZARD_TYPES.map((hazard) => {
                    const Icon = hazard.icon
                    const count = hazard.type === "ALL" 
                      ? alerts.length 
                      : hazardCounts[hazard.type] || 0
                    const isActive = hazardTypeFilter === hazard.type
                    
                    return (
                      <Button
                        key={hazard.type}
                        variant={isActive ? "default" : "outline"}
                        size="sm"
                        onClick={() => setHazardTypeFilter(hazard.type)}
                        className={cn(
                          "h-7 text-xs gap-1.5",
                          isActive && hazard.type !== "ALL" && hazard.color.replace("bg-", "bg-") + " text-white"
                        )}
                      >
                        <Icon className="h-3 w-3" />
                        {hazard.label}
                        <Badge variant="secondary" className="ml-1 h-4 text-[9px] px-1">
                          {count}
                        </Badge>
                      </Button>
                    )
                  })}
                  {(hazardTypeFilter !== "ALL" || severityFilter) && (
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={clearFilters}
                      className="h-7 text-xs gap-1.5 text-muted-foreground"
                    >
                      <X className="h-3 w-3" />
                      Clear
                    </Button>
                  )}
                </div>

                {/* Map */}
                <div className="h-[400px] lg:h-[480px]">
                  <AfricaMap
                    alerts={filteredAlerts}
                    onAlertClick={handleAlertClick}
                  />
                </div>
              </div>

              {/* Alert panel - 1/3 */}
              <div className="h-[440px] lg:h-[520px] rounded-lg border border-border bg-card overflow-hidden flex flex-col">
                <div className="px-3 py-2.5 border-b border-border shrink-0">
                  <div className="flex items-center gap-2">
                    <AlertTriangle className="h-4 w-4 text-severity-orange" />
                    <h2 className="text-sm font-semibold text-foreground">
                      Active Alerts
                    </h2>
                    {filteredAlerts.length > 0 && (
                      <span className="text-[10px] font-mono text-muted-foreground bg-secondary px-1.5 py-0.5 rounded">
                        {filteredAlerts.length}
                      </span>
                    )}
                  </div>
                  {severityFilter && (
                    <div className="flex items-center gap-1 mt-1.5">
                      <span className="text-[10px] text-muted-foreground">Severity:</span>
                      <Badge 
                        variant="outline" 
                        className={cn(
                          "text-[10px] h-4 px-1",
                          severityFilter === "RED" && "border-severity-red text-severity-red",
                          severityFilter === "ORANGE" && "border-severity-orange text-severity-orange",
                          severityFilter === "YELLOW" && "border-severity-yellow text-severity-yellow",
                        )}
                      >
                        {severityFilter}
                      </Badge>
                    </div>
                  )}
                </div>
                <AlertPanel
                  alerts={filteredAlerts}
                  onAlertClick={handleAlertClick}
                  selectedSeverity={severityFilter}
                  onSeverityFilter={setSeverityFilter}
                  compact
                />
              </div>
            </div>

            {/* Hazard Visualizations Grid */}
            <div className="grid grid-cols-1 xl:grid-cols-2 gap-4">
              <CycloneTrackVisualization />
              <FloodMonitorVisualization />
              <DroughtMonitorVisualization />
              <WildfireTrackerVisualization />
            </div>

            {/* Weather + Hazard Distribution */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
              <WeatherPanel data={weatherData} isLoading={weatherLoading} />
              <div className="rounded-lg border border-border bg-card p-4">
                <div className="flex items-center gap-2 mb-4">
                  <BarChart3 className="h-4 w-4 text-primary" />
                  <h3 className="text-sm font-semibold text-foreground">
                    Hazard Distribution
                  </h3>
                </div>
                <HazardChart alerts={alerts} />
              </div>
            </div>
          </div>
        )}

        {/* ========== ACTIVE ALERTS (Full List) ========== */}
        {currentView === "alerts" && (
          <div className="space-y-4">
            <div className="flex items-center gap-2">
              <AlertTriangle className="h-5 w-5 text-severity-orange" />
              <h2 className="text-lg font-bold text-foreground">
                Active Alerts
              </h2>
              <span className="text-sm text-muted-foreground">
                ({alerts.length} total)
              </span>
            </div>
            <SeverityStats alerts={alerts} />
            <div className="rounded-lg border border-border bg-card overflow-hidden" style={{ height: "calc(100vh - 340px)" }}>
              <AlertPanel
                alerts={alerts}
                onAlertClick={handleAlertClick}
                selectedSeverity={severityFilter}
                onSeverityFilter={setSeverityFilter}
              />
            </div>
          </div>
        )}

        {/* ========== WEATHER INTEL ========== */}
        {currentView === "weather" && (
          <div className="space-y-4">
            <div className="flex items-center gap-2">
              <Cloud className="h-5 w-5 text-primary" />
              <h2 className="text-lg font-bold text-foreground">
                Weather Intelligence
              </h2>
            </div>
            <WeatherPanel data={weatherData} isLoading={weatherLoading} />
          </div>
        )}

        {/* ========== COMMUNITY FIELD REPORTS ========== */}
        {currentView === "community" && (
          <div className="space-y-4">
            <div className="flex items-center gap-2">
              <Users className="h-5 w-5 text-primary" />
              <h2 className="text-lg font-bold text-foreground">
                Community Field Reports
              </h2>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
              <div className="rounded-lg border border-border bg-card p-4">
                <div className="flex items-center gap-2 mb-4">
                  <Plus className="h-4 w-4 text-primary" />
                  <h3 className="text-sm font-semibold text-foreground">
                    Submit a Field Report
                  </h3>
                </div>
                <CommunityReportForm
                  onSubmitSuccess={() => mutateReports()}
                />
              </div>

              <div className="rounded-lg border border-border bg-card p-4">
                <div className="flex items-center gap-2 mb-4">
                  <FileText className="h-4 w-4 text-primary" />
                  <h3 className="text-sm font-semibold text-foreground">
                    Recent Reports
                  </h3>
                  <span className="text-[10px] font-mono text-muted-foreground bg-secondary px-1.5 py-0.5 rounded">
                    {reports.length}
                  </span>
                </div>
                <ReportsList reports={reports} isLoading={reportsLoading} />
              </div>
            </div>
          </div>
        )}

        {/* ========== DATA PIPELINE ========== */}
        {currentView === "pipeline" && (
          <div className="space-y-4">
            <div className="flex items-center gap-2">
              <Database className="h-5 w-5 text-primary" />
              <h2 className="text-lg font-bold text-foreground">
                Data Pipeline
              </h2>
            </div>
            <PipelineStatus
              data={pipelineData}
              isLoading={pipelineLoading}
            />
          </div>
        )}
      </main>

      {selectedAlert && (
        <AlertDetail
          alert={selectedAlert}
          onClose={() => setSelectedAlert(null)}
        />
      )}
    </DashboardShell>
  )
}
